"""Generate the parameter tables of docs/dashboard_spec.md (§5) from src/parameters.jl.
   python3 scripts/dashboard_tables.py > /tmp/param_tables.md   (16 October 2026)"""
import re, sys, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = open(os.path.join(ROOT, 'src', 'parameters.jl')).read()
params, pending = [], []
for ln in src.split('\n'):
    m = re.match(r'^    ([a-z_0-9]+)::([A-Za-z0-9_{}, .]+?)\s*=\s*(.+?)\s*(#\s*(.*))?$', ln)
    if m:
        name, typ, default, _, comment = m.groups()
        pre = ' '.join(x.strip().lstrip('#').strip() for x in pending)
        params.append((name, typ.strip(), default.strip(), (comment or pre or '').strip()))
        pending = []
    elif ln.strip().startswith('#'):
        pending.append(ln)
    elif not ln.strip():
        pending = []
groups = [
 ("Village", r"^(spoilage_aware|number_of_|initial_|land_per|maximum_capacity|capacity_recovery|half_meal|rounds_without_food|breads_per_|customers_per|theatre_|shows_per|entertainment|spoilage_age|stock_|demand_based|initial_production|price_multiplier|maximum_breads|gluttony|stocking|bread_rationing|ration_|tiered|tier_step|no_self|harvest|seats_per|max_tickets)"),
 ("Money", r"^(monetary_system|guaranteed_income|demurrage|parking|deposit_interest|loyalty_bonus|interest_|maximum_interest|minimum_interest|bank_|lending|government_rate|bond|peer_lend|peer_loan|buffer_|default_insurance|instalment_|start_at|initial_money|credit_|affordability|loan_term|founding_loan|collection_floor|receivables|owner_guarantee|guarantee_|capital_constrains|capital_ratio|debt_dies|interbank|arrears_rounds|garnishment|inherited_money|bread_loan|deferred_payment|insurance_premium|account_fee|clearing)"),
 ("Government", r"^(bracket_|government_|wage_tax|capital_tax|profit_tax|consumption_tax|wealth_tax|dividend_tax|income_tax|tax_|unemployment_|minimum_fee|fee_reduction|employment_rounds|partial_unemployment|surplus_|austerity|benefit_|public_|basic_income|income_cut|social_contribution|municipal|enterprise_tax|enterprise_income|enterprise_reserve|reserve_tax|deductible)"),
 ("Prices and bargaining", r"^(ask_|bid_|negotiation|unmet_demand|unsold_|expected_price|wage_ceiling|bread_bid|ticket_max|employer_wage_margin|fixed_prices|reserve_pricing|price_|minimum_concession|maximum_concession|bread_price_ageing|farm_maximum_rent|bakery_grain_wage|indexed_pricing|greedy_pricing|distress_)"),
 ("Labour", r"^(joint_labour|contract|worker_notice|worker_leave|experience|offer_full|wage_threshold|wage_cut|wage_floor|employer_loyalty|notice_|food_emergency|employer_loss|minimum_labour|volunteer|standard_of_living|random_hiring|no_labour|members_first|minimum_member|hunger_wage|labour_for_bread|wage_reservation|savings_)"),
 ("Firms, planning, ownership and entry", r"^(ownership|shareholder|founders|founding_equity|share_|shares_|cooperative|patronage|retained_surplus|capital_deduction|membership|dividend_|startup_|required_yield|forward_valuation|founder_|expected_price_growth|liquidation|liquidated|closure_|settlement|refound|market_entry|entry_|arrears_de_minimis|stop_without|reserve_target|reserve_protection|member_price|planning_margin|plan_|firms_plan|bakery_capacity|community_|premium_)"),
 ("Land and gold", r"^(land_|distress_land|gold_|levy_)"),
 ("Behaviour variants", r"^(greed|greedy_|cash_hoarder|spoilage_acceptance|nonworking)"),
 ("Run control", r"^(random_streams|maximum_rounds|stationary|seed|save_|record_|stop_when)"),
]
out = {g: [] for g, _ in groups}; other = []
for row in params:
    for g, pat in groups:
        if re.match(pat, row[0]): out[g].append(row); break
    else: other.append(row)
def sweep(t): return "yes" if t in ("Float64", "Int", "Bool") else "list" if t.startswith("Symbol") else "no"
esc = lambda x: x.replace('|', '\\|')
print(f"<!-- generated by scripts/dashboard_tables.py from src/parameters.jl: {len(params)} parameters -->")
for g, _ in groups + ([("Other", None)] if other else []):
    rows = out.get(g, other if g == "Other" else [])
    print(f"\n### {g} — {len(rows)} parameters\n\n| parameter | type | default | sweep | meaning |\n|---|---|---|---|---|")
    for n, t, d, c in rows:
        print(f"| `{n}` | {t} | `{esc(d)}` | {sweep(t)} | {esc(c)[:170]} |")
if other: print("UNPLACED:", [r[0] for r in other], file=sys.stderr)
